using Maxx.Domain.Conquistas;
using Maxx.Domain.Premios;

namespace Maxx.Domain.Notificacoes;

// Registro no banco, mostrado no sininho do feed a partir do passo 10 (produto.md 8). No
// passo 6 nasce o primeiro tipo, a medalha recebida. A referência aponta para o que gerou
// a notificação (a medalha, aqui); o texto é do cliente, a partir do tipo.
public sealed class Notificacao
{
    // Para o EF Core materializar do banco.
    private Notificacao()
    {
    }

    private Notificacao(Guid usuarioId, TipoDeNotificacao tipo, Guid referenciaId, DateTimeOffset agora)
    {
        Id = Guid.CreateVersion7();
        UsuarioId = usuarioId;
        Tipo = tipo;
        ReferenciaId = referenciaId;
        CriadaEm = agora;
    }

    public Guid Id { get; private set; }

    public Guid UsuarioId { get; private set; }

    public TipoDeNotificacao Tipo { get; private set; }

    public Guid ReferenciaId { get; private set; }

    public DateTimeOffset CriadaEm { get; private set; }

    public DateTimeOffset? LidaEm { get; private set; }

    // Só medalha ativa notifica: a anulada antes de o trabalho rodar não chega ao aluno.
    public static Notificacao MedalhaRecebida(Medalha medalha, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(medalha);
        if (!medalha.EstaAtiva)
        {
            throw new DomainException($"A medalha {medalha.Id} está anulada e não notifica.");
        }

        return new Notificacao(medalha.AlunoId, TipoDeNotificacao.MedalhaRecebida, medalha.Id, agora);
    }

    // Comprovação aprovada (passo 8): o prêmio foi aprovado, mesmo que depois contestado.
    public static Notificacao ComprovacaoAprovada(PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(premio);
        if (premio.AprovadoEm is null)
        {
            throw new DomainException($"O prêmio {premio.Id} não foi aprovado.");
        }

        return new Notificacao(premio.AlunoId, TipoDeNotificacao.ComprovacaoAprovada, premio.Id, agora);
    }

    // Comprovação reprovada: o motivo o app lê do prêmio.
    public static Notificacao ComprovacaoReprovada(PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(premio);
        if (premio.Estado != EstadoDoPremioParticipacao.Reprovado)
        {
            throw new DomainException($"O prêmio {premio.Id} não foi reprovado.");
        }

        return new Notificacao(premio.AlunoId, TipoDeNotificacao.ComprovacaoReprovada, premio.Id, agora);
    }

    // Contestação aberta sobre um prêmio do aluno (produto.md 8). A referência é o prêmio:
    // uma contestação por prêmio.
    public static Notificacao ContestacaoAberta(PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(premio);
        if (premio.ContestadoEm is null)
        {
            throw new DomainException($"O prêmio {premio.Id} não foi contestado.");
        }

        return new Notificacao(premio.AlunoId, TipoDeNotificacao.ContestacaoAberta, premio.Id, agora);
    }

    // A instituição decidiu a contestação: confirmou ou revogou. O app lê qual no prêmio.
    public static Notificacao DecisaoDeContestacao(PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(premio);
        if (premio.ContestadoEm is null
            || premio.Estado is not (EstadoDoPremioParticipacao.Definitivo or EstadoDoPremioParticipacao.Revogado))
        {
            throw new DomainException($"O prêmio {premio.Id} não tem contestação decidida.");
        }

        return new Notificacao(premio.AlunoId, TipoDeNotificacao.DecisaoDeContestacao, premio.Id, agora);
    }

    // Prêmio válido revogado sem contestação: só pela remoção do post pela instituição.
    public static Notificacao PremioRevogado(PremioParticipacao premio, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(premio);
        if (premio.Estado != EstadoDoPremioParticipacao.Revogado)
        {
            throw new DomainException($"O prêmio {premio.Id} não foi revogado.");
        }

        return new Notificacao(premio.AlunoId, TipoDeNotificacao.PremioRevogado, premio.Id, agora);
    }

    // Conquista obtida (passo 9, fluxos/03-concessao-de-medalha.md): o sistema a concedeu.
    public static Notificacao ConquistaObtida(Conquista conquista, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(conquista);
        if (!conquista.EstaAtiva)
        {
            throw new DomainException($"A conquista {conquista.Id} foi removida e não notifica como obtida.");
        }

        return new Notificacao(conquista.AlunoId, TipoDeNotificacao.ConquistaObtida, conquista.Id, agora);
    }

    // Conquista removida pelo recálculo depois de uma anulação (regras-conquista.md 6): os
    // pontos saíram, e o aluno fica sabendo.
    public static Notificacao ConquistaRemovida(Conquista conquista, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(conquista);
        if (conquista.EstaAtiva)
        {
            throw new DomainException($"A conquista {conquista.Id} não foi removida.");
        }

        return new Notificacao(conquista.AlunoId, TipoDeNotificacao.ConquistaRemovida, conquista.Id, agora);
    }
}

public enum TipoDeNotificacao
{
    MedalhaRecebida,
    ComprovacaoAprovada,
    ComprovacaoReprovada,
    ContestacaoAberta,
    DecisaoDeContestacao,
    PremioRevogado,
    ConquistaObtida,
    ConquistaRemovida,
}
using Maxx.Application.Notificacoes;
using Maxx.Domain.Notificacoes;
using Maxx.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Maxx.Infrastructure.Notificacoes;

internal sealed class NotificacaoRepository(MaxxDbContext db) : INotificacaoRepository
{
    public void Adicionar(Notificacao notificacao) => db.Add(notificacao);

    public Task<bool> ExisteAsync(Guid usuarioId, TipoDeNotificacao tipo, Guid referenciaId, CancellationToken cancellationToken) =>
        db.Set<Notificacao>().AnyAsync(
            notificacao => notificacao.UsuarioId == usuarioId && notificacao.Tipo == tipo && notificacao.ReferenciaId == referenciaId,
            cancellationToken);
}
using Maxx.Domain.Catalogo;
using Maxx.Domain.Identidade;
using Maxx.Domain.Notificacoes;
using Maxx.Infrastructure.RaridadeDosItens;
using Maxx.Infrastructure.Seed;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Maxx.Infrastructure.Persistence.Configurations;

internal sealed class NotificacaoConfiguration : IEntityTypeConfiguration<Notificacao>
{
    public void Configure(EntityTypeBuilder<Notificacao> builder)
    {
        builder.ToTable("notificacao", table =>
            table.HasCheckConstraint("ck_notificacao_tipo", $"tipo IN ({Lista<TipoDeNotificacao>()})"));
        builder.HasKey(notificacao => notificacao.Id);
        builder.Property(notificacao => notificacao.Id).ValueGeneratedNever();
        builder.Property(notificacao => notificacao.Tipo)
            .HasConversion(tipo => NomeJson.De(tipo), texto => Enum.Parse<TipoDeNotificacao>(texto, ignoreCase: true));

        // Uma notificação por fato e por usuário: o trabalho que roda de novo não duplica.
        builder.HasIndex(notificacao => new { notificacao.UsuarioId, notificacao.Tipo, notificacao.ReferenciaId }).IsUnique();

        // A referência é genérica (medalha hoje; aprovação, aviso depois): sem chave
        // estrangeira. A purga apaga as notificações do usuário antes dele.
        builder.HasOne<Usuario>().WithMany().HasForeignKey(notificacao => notificacao.UsuarioId).OnDelete(DeleteBehavior.Restrict);
    }

    private static string Lista<T>()
        where T : struct, Enum => string.Join(", ", Enum.GetValues<T>().Select(valor => $"'{NomeJson.De(valor)}'"));
}

internal sealed class RaridadeDoItemConfiguration : IEntityTypeConfiguration<RaridadeDoItemRow>
{
    public void Configure(EntityTypeBuilder<RaridadeDoItemRow> builder)
    {
        builder.ToTable("raridade_do_item", table =>
        {
            table.HasCheckConstraint(
                "ck_raridade_do_item_raridade",
                $"raridade IN ({string.Join(", ", Enum.GetValues<Raridade>().Select(valor => $"'{NomeJson.De(valor)}'"))})");
            table.HasCheckConstraint(
                "ck_raridade_do_item_contagem", "alunos_com_item >= 0 AND alunos_com_item <= alunos_elegiveis");
        });
        builder.HasKey(linha => linha.ItemCodigo);

        // A raridade é do item: sai com ele, se um dia o item sair do catálogo.
        builder.HasOne<ItemCatalogoRow>().WithOne().HasForeignKey<RaridadeDoItemRow>(linha => linha.ItemCodigo)
            .OnDelete(DeleteBehavior.Cascade);
    }
}

internal sealed class RecalculoConfiguration : IEntityTypeConfiguration<RecalculoRow>
{
    public void Configure(EntityTypeBuilder<RecalculoRow> builder)
    {
        builder.ToTable("recalculo");
        builder.HasKey(linha => linha.Nome);
        builder.Property(linha => linha.Nome).HasMaxLength(50);
    }
}
using Maxx.Application.Fila;
using Maxx.Application.Medalhas;
using Maxx.Domain.Notificacoes;

namespace Maxx.Application.Notificacoes;

public interface INotificacaoRepository
{
    void Adicionar(Notificacao notificacao);

    Task<bool> ExisteAsync(Guid usuarioId, TipoDeNotificacao tipo, Guid referenciaId, CancellationToken cancellationToken);
}

// No worker: grava a notificação de medalha recebida (produto.md 8). Uma por medalha, mesmo
// que o trabalho rode de novo; nenhuma para medalha que já foi anulada ou apagada pela purga.
public sealed class NotificarMedalhaRecebidaHandler(
    IMedalhaRepository medalhas,
    INotificacaoRepository notificacoes,
    IUnitOfWork unitOfWork,
    TimeProvider relogio) : ITrabalhoHandler<NotificarMedalhaRecebida>
{
    public async Task ExecutarAsync(NotificarMedalhaRecebida carga, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(carga);

        var medalha = await medalhas.BuscarAsync(carga.MedalhaId, cancellationToken);
        if (medalha is null || !medalha.EstaAtiva
            || await notificacoes.ExisteAsync(medalha.AlunoId, TipoDeNotificacao.MedalhaRecebida, medalha.Id, cancellationToken))
        {
            return;
        }

        notificacoes.Adicionar(Notificacao.MedalhaRecebida(medalha, relogio.GetUtcNow()));
        await unitOfWork.SalvarAsync(cancellationToken);
    }
}
