import { useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { useState } from "react";
import {
  ActivityIndicator,
  FlatList,
  Pressable,
  RefreshControl,
  StyleSheet,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { falhaParaTela } from "../api/FalhaDaApi";
import { useEu } from "../api/useEu";
import { Icon } from "../components/Icon";
import { EmptyState, ErrorState } from "../components/StateMessage";
import { Logo } from "../marca/Logo";
import { useTheme } from "../theme/ThemeProvider";
import { espacamento, tamanhos } from "../theme/tokens";
import { useFeed } from "./api";
import { CartaoDePost } from "./CartaoDePost";

// A Home (produto.md 6.2 e prancheta do feed): o logo e o "+" do novo post no topo, e os
// posts de quem a pessoa segue intercalados com recomendações, rolando sem fim. O sininho
// chega com as notificações, no passo 10.
export function FeedScreen() {
  const { colors } = useTheme();
  const insets = useSafeAreaInsets();
  const router = useRouter();
  const queryClient = useQueryClient();
  const eu = useEu();
  const feed = useFeed();
  const [atualizando, setAtualizando] = useState(false);

  const ehAluno = eu.data?.papeis.includes("aluno") ?? false;
  const posts = feed.data?.pages.flatMap((pagina) => pagina.itens) ?? [];

  // Puxar para atualizar começa uma sessão nova: outra semente, outra ordem de recomendações.
  const atualizar = async () => {
    setAtualizando(true);
    try {
      await queryClient.resetQueries({ queryKey: ["feed"] });
    } finally {
      setAtualizando(false);
    }
  };

  const cabecalho = (
    <View style={styles.topo}>
      <Logo largura={110} />
      {ehAluno && (
        <Pressable
          role="button"
          accessibilityLabel="Novo post"
          hitSlop={8}
          onPress={() => router.push("/novo-post")}
          style={styles.botao}
        >
          <Icon name="novo" color={colors.ink} size={tamanhos.iconeNav} />
import { useRouter, type Href } from "expo-router";
import { Pressable, StyleSheet, Text, View } from "react-native";

import { textStyles } from "../theme/fonts";
import { useTheme } from "../theme/ThemeProvider";
import { tamanhos } from "../theme/tokens";
import { Icon } from "./Icon";

interface CabecalhoProps {
  titulo: string;
  // Para onde volta quando não há tela anterior (a página foi aberta direto pelo link).
  voltarPara: Href;
}

// O topo de uma tela interna, como o do Instagram: voltar à esquerda e o título. Sem
// sombra: a separação é a linha de 1 px em `line`.
export function Cabecalho({ titulo, voltarPara }: CabecalhoProps) {
  const { colors } = useTheme();
  const router = useRouter();

  return (
    <View style={[styles.barra, { borderBottomColor: colors.line }]}>
      <Pressable
        role="button"
        accessibilityLabel="Voltar"
        hitSlop={8}
        style={({ pressed }) => [styles.voltar, pressed && styles.pressionado]}
        onPress={() =>
          router.canGoBack() ? router.back() : router.replace(voltarPara)
        }
      >
        <Icon name="voltar" color={colors.ink} size={tamanhos.iconeNav} />
      </Pressable>
      <Text
        role="heading"
        numberOfLines={1}
        style={[textStyles.secao, styles.titulo, { color: colors.ink }]}
      >
        {titulo}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  barra: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    minHeight: tamanhos.alvoDeToque + 8,
    borderBottomWidth: 1,
    marginBottom: 8,
  },
  voltar: {
    width: tamanhos.alvoDeToque,
    height: tamanhos.alvoDeToque,
    alignItems: "center",
    justifyContent: "center",
    marginLeft: -12,
  },
import { Slot, usePathname, useRouter, type Href } from "expo-router";
import { StyleSheet, View } from "react-native";

import { useEu } from "../api/useEu";
import { BottomNav, type Aba } from "../components/BottomNav";
import { useTheme } from "../theme/ThemeProvider";

const ROTAS: Record<Aba, Href> = {
  home: "/",
  busca: "/busca",
  mural: "/mural",
  trofeus: "/trofeus",
  perfil: "/perfil",
};

export function abaDaRota(caminho: string): Aba {
  const encontrada = (Object.entries(ROTAS) as [Aba, string][]).find(
    ([aba, rota]) => aba !== "home" && caminho.startsWith(rota),
  );
  return encontrada?.[0] ?? "home";
}

// As cinco abas, na ordem do design: Home, Busca, Mural, Troféus, Perfil (produto.md 10).
// Desde o passo 6, com Troféus de verdade; Busca, Mural e Perfil chegam nos passos 7 e 10.
// A bolinha de novidade chega com o sininho, no passo 10.
export function LayoutDasAbas() {
  const { colors } = useTheme();
  const router = useRouter();
  const caminho = usePathname();
  const eu = useEu();

  return (
    <View style={[styles.fill, { backgroundColor: colors.bg }]}>
      <View style={styles.fill}>
        <Slot />
      </View>
      <BottomNav
        active={abaDaRota(caminho)}
        nome={eu.data?.nomeDeExibicao ?? ""}
        onSelect={(aba) => router.navigate(ROTAS[aba])}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  fill: { flex: 1 },
});
