using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;

namespace Maxx.Domain.Fotos;

// O pedido de envio de uma foto, nas duas derivadas que o app gera (ADR 0003): a do feed
// (~1080²) e a da grade (~320²). A API assina as duas URLs e registra o pedido; quem usa a
// foto (o post, a foto de perfil) confirma. O que não for confirmado sai do bucket e do
// banco pela fila, passado o prazo de limpeza (ADR 0002).
public sealed class UploadPendente
{
    // O app reencoda tudo antes de enviar (ADR 0003): só JPEG chega ao bucket.
    public const string TipoAceito = "image/jpeg";

    // 1 MiB e 200 KiB: folga sobre um JPEG de 1080² e de 320² em qualidade de foto.
    public const long TamanhoMaximoDoFeed = 1024 * 1024;
    public const long TamanhoMaximoDaGrade = 200 * 1024;

    // Quanto tempo o app tem para fazer o PUT depois de pedir.
    public static readonly TimeSpan ValidadeDaAssinatura = TimeSpan.FromMinutes(15);

    // Quando a fila apaga o que ninguém confirmou. Bem depois da validade: um envio lento
    // terminado no último minuto ainda tem horas para virar post.
    public static readonly TimeSpan PrazoDeLimpeza = TimeSpan.FromHours(24);

    // Para o EF Core materializar do banco.
    private UploadPendente()
    {
        ChaveDoFeed = null!;
        ChaveDaGrade = null!;
        TipoDeConteudo = null!;
    }

    private UploadPendente(
        Guid usuarioId, FinalidadeDoUpload finalidade, string identificador, long tamanhoDoFeed, long tamanhoDaGrade, DateTimeOffset agora)
    {
        Id = Guid.CreateVersion7();
        UsuarioId = usuarioId;
        Finalidade = finalidade;
        ChaveDoFeed = $"{identificador}/feed.jpg";
        ChaveDaGrade = $"{identificador}/grade.jpg";
        TipoDeConteudo = TipoAceito;
        TamanhoDoFeed = tamanhoDoFeed;
        TamanhoDaGrade = tamanhoDaGrade;
        CriadoEm = agora;
    }

    public Guid Id { get; private set; }

    public Guid UsuarioId { get; private set; }

    public FinalidadeDoUpload Finalidade { get; private set; }

    // Aleatórias: a leitura é pública para quem tem o link.
    public string ChaveDoFeed { get; private set; }

    public string ChaveDaGrade { get; private set; }

    public string TipoDeConteudo { get; private set; }

    public long TamanhoDoFeed { get; private set; }

    public long TamanhoDaGrade { get; private set; }

    public DateTimeOffset CriadoEm { get; private set; }

    public DateTimeOffset? ConfirmadoEm { get; private set; }

    public bool EstaConfirmado => ConfirmadoEm is not null;

    public DateTimeOffset AssinaturaExpiraEm => CriadoEm + ValidadeDaAssinatura;

    public DateTimeOffset LimparEm => CriadoEm + PrazoDeLimpeza;

    public IReadOnlyList<string> Chaves => [ChaveDoFeed, ChaveDaGrade];

    // Quem usa a foto confirma, e a limpeza da fila passa a deixá-la em paz. Uma vez só: a
    // mesma foto não vira dois posts.
    internal void Confirmar(DateTimeOffset agora)
    {
        if (EstaConfirmado)
        {
            throw new DomainException($"O upload {Id} já foi usado.");
        }

        ConfirmadoEm = agora;
    }

    // Recusa em vez de exceção: a borda responde com o código de cada caso. O tipo é
    // comparado como o HTTP compara, sem diferenciar maiúsculas, e gravado na forma canônica,
    // que é a que vai presa na assinatura.
    public static ResultadoDoPedidoDeUpload Pedir(
        Usuario usuario,
        FinalidadeDoUpload finalidade,
        string? tipoDeConteudo,
        long tamanhoDoFeed,
        long tamanhoDaGrade,
        DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(usuario);

        if (!PodeEnviar(usuario, finalidade))
        {
            return new(null, RecusaDoUpload.FinalidadeNaoPermitida);
        }

        if (!string.Equals(tipoDeConteudo?.Trim(), TipoAceito, StringComparison.OrdinalIgnoreCase))
        {
            return new(null, RecusaDoUpload.TipoNaoAceito);
        }

        if (tamanhoDoFeed is < 1 or > TamanhoMaximoDoFeed || tamanhoDaGrade is < 1 or > TamanhoMaximoDaGrade)
        {
            return new(null, RecusaDoUpload.TamanhoInvalido);
        }

        return new(new UploadPendente(usuario.Id, finalidade, Ulid.Novo(agora), tamanhoDoFeed, tamanhoDaGrade, agora), null);
    }

    // Post é só de aluno que não virou ex-aluno (produto.md 2.2 e 6.1). Foto de perfil, de
    // aluno e de professor (produto.md 2.3); a instituição não tem perfil social.
    public static bool PodeEnviar(Usuario usuario, FinalidadeDoUpload finalidade)
    {
        ArgumentNullException.ThrowIfNull(usuario);
        return finalidade switch
        {
            FinalidadeDoUpload.Post => usuario.Papeis == Papeis.Aluno && !usuario.EhExAluno,
            FinalidadeDoUpload.FotoDePerfil => usuario.Papeis.HasFlag(Papeis.Aluno) || usuario.Papeis.HasFlag(Papeis.Professor),
            _ => false,
        };
    }
}

public enum FinalidadeDoUpload
{
    Post,
    FotoDePerfil,
}

public enum RecusaDoUpload
{
    FinalidadeNaoPermitida,
    TipoNaoAceito,
    TamanhoInvalido,
}

public sealed record ResultadoDoPedidoDeUpload(UploadPendente? Upload, RecusaDoUpload? Recusa);
using Maxx.Application.Autenticacao;
using Maxx.Application.Fila;
using Maxx.Domain.Fotos;

namespace Maxx.Application.Fotos;

public interface IUploadPendenteRepository
{
    void Adicionar(UploadPendente upload);

    Task<UploadPendente?> BuscarAsync(Guid id, CancellationToken cancellationToken);

    void Remover(UploadPendente upload);
}

// O pedido assinado: o registro e as duas URLs de PUT, uma por derivada.
public sealed record UploadAssinado(UploadPendente Upload, EnvioAssinado Feed, EnvioAssinado Grade);

// Pedido de envio (fluxos/02-post-com-comprovacao.md): valida quem pede, o tipo e o tamanho
// das duas derivadas, registra o upload pendente e devolve as URLs assinadas. A limpeza do
// que não for confirmado já sai enfileirada, adiada até o prazo, na mesma transação: não há
// upload pendente sem o trabalho que o apaga (ADR 0008).
public sealed class PedirUploadHandler(
    IUsuarioRepository usuarios,
    IUploadPendenteRepository uploads,
    IArmazenamentoDeFotos armazenamento,
    IFilaDeTrabalhos fila,
    IUnitOfWork unitOfWork,
    TimeProvider relogio)
{
    public async Task<UploadAssinado> PedirAsync(
        Guid usuarioId,
        FinalidadeDoUpload finalidade,
        string? tipoDeConteudo,
        long tamanhoDoFeed,
        long tamanhoDaGrade,
        CancellationToken cancellationToken)
    {
        // Token válido de uma conta que já não existe (a purga da demonstração).
        var usuario = await usuarios.BuscarAsync(usuarioId, cancellationToken)
            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {usuarioId} não existe.");

        var resultado = UploadPendente.Pedir(usuario, finalidade, tipoDeConteudo, tamanhoDoFeed, tamanhoDaGrade, relogio.GetUtcNow());
        if (resultado.Upload is not { } upload)
        {
            throw Recusa(resultado.Recusa!.Value, usuarioId, finalidade);
        }

        // Assinar não vai à rede: se falhar, é configuração, e nada foi gravado.
        var feed = armazenamento.AssinarEnvio(upload.ChaveDoFeed, upload.TipoDeConteudo, upload.TamanhoDoFeed, upload.AssinaturaExpiraEm);
        var grade = armazenamento.AssinarEnvio(upload.ChaveDaGrade, upload.TipoDeConteudo, upload.TamanhoDaGrade, upload.AssinaturaExpiraEm);

        uploads.Adicionar(upload);
        fila.Enfileirar(new LimparUploadAbandonado(upload.Id), upload.LimparEm);
        await unitOfWork.SalvarAsync(cancellationToken);
        return new UploadAssinado(upload, feed, grade);
    }

    private static RecusaException Recusa(RecusaDoUpload recusa, Guid usuarioId, FinalidadeDoUpload finalidade) => recusa switch
    {
        RecusaDoUpload.FinalidadeNaoPermitida => new RecusaException(
            TipoDeRecusa.Proibido, CodigosDaFoto.EnvioNaoPermitido, $"Usuário {usuarioId} não envia foto para {finalidade}."),
        RecusaDoUpload.TipoNaoAceito => new RecusaException(
            TipoDeRecusa.Invalido, CodigosDaFoto.TipoDeFotoNaoAceito, "Tipo de foto fora do aceito."),
        RecusaDoUpload.TamanhoInvalido => new RecusaException(
            TipoDeRecusa.Invalido, CodigosDaFoto.TamanhoDeFotoInvalido, "Tamanho de foto fora da faixa."),
        _ => throw new ArgumentOutOfRangeException(nameof(recusa), recusa, null),
    };
}

// O upload pendente que ninguém confirmou até o prazo de limpeza sai do bucket e do banco.
public sealed record LimparUploadAbandonado(Guid UploadId) : ICargaDeTrabalho
{
    public static string Tipo => "limpar-upload-abandonado";
}

// No worker. A linha sai primeiro, e o DELETE, com o xmin, segura a linha até o trabalho
// terminar: uma confirmação que chegue agora espera e encontra a linha já apagada, em vez
// de confirmar um upload cujos objetos estão saindo. Depois saem os objetos. Se a remoção
// no bucket falha, o trabalho desfaz o DELETE e volta com recuo; se o trabalho roda de novo
// depois de remover, não acha nada e termina. Confirmado antes, não toca em nada.
public sealed class LimparUploadAbandonadoHandler(
    IUploadPendenteRepository uploads,
    IArmazenamentoDeFotos armazenamento,
    IUnitOfWork unitOfWork) : ITrabalhoHandler<LimparUploadAbandonado>
{
    public async Task ExecutarAsync(LimparUploadAbandonado carga, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(carga);

        var upload = await uploads.BuscarAsync(carga.UploadId, cancellationToken);
        if (upload is null || upload.EstaConfirmado)
        {
            return;
        }

        uploads.Remover(upload);
        await unitOfWork.SalvarAsync(cancellationToken);
        await armazenamento.RemoverAsync(upload.Chaves, cancellationToken);
    }
}

// Fotos que já foram usadas e deixaram de ser: post apagado ou removido, foto de perfil
// trocada. As chaves não são segredo, só endereço.
public sealed record RemoverFotos(IReadOnlyList<string> Chaves) : ICargaDeTrabalho
{
    public static string Tipo => "remover-fotos";
}

// No worker. Remover chave que já não existe não é erro: o trabalho pode rodar de novo.
public sealed class RemoverFotosHandler(IArmazenamentoDeFotos armazenamento) : ITrabalhoHandler<RemoverFotos>
{
    public async Task ExecutarAsync(RemoverFotos carga, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(carga);
        await armazenamento.RemoverAsync(carga.Chaves, cancellationToken);
    }
}
namespace Maxx.Application;

// Um pedido que a aplicação recusa por regra, não por falha: a borda traduz o tipo em
// status HTTP e devolve o código no formato único de erro. A mensagem é só para o log.
public sealed class RecusaException : Exception
{
    public RecusaException()
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message) : base(message)
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message, Exception innerException) : base(message, innerException)
    {
        Codigo = string.Empty;
    }

    public RecusaException(TipoDeRecusa tipo, string codigo, string? motivoParaLog = null)
        : base(motivoParaLog ?? codigo)
    {
        Tipo = tipo;
        Codigo = codigo;
    }

    public TipoDeRecusa Tipo { get; }

    // Estável e em kebab-case: é o que o cliente usa para escolher a mensagem amigável.
    public string Codigo { get; }
}

public enum TipoDeRecusa
{
    Invalido,
    NaoEncontrado,
    Conflito,
    NaoAutorizado,

    // Autenticado, mas sem direito sobre o recurso: o escopo de turma do professor.
    Proibido,
}

// Gravação recusada por uma unicidade do banco: a corrida que a checagem prévia não
// consegue fechar sozinha.
public sealed class ConflitoDeUnicidadeException : Exception
{
    public ConflitoDeUnicidadeException()
    {
    }

    public ConflitoDeUnicidadeException(string message) : base(message)
    {
    }

    public ConflitoDeUnicidadeException(string message, Exception innerException) : base(message, innerException)
    {
    }

    public ConflitoDeUnicidadeException(Unicidade unicidade, Exception innerException)
        : base($"Unicidade violada: {unicidade}.", innerException)
    {
        Unicidade = unicidade;
    }

    public Unicidade Unicidade { get; }
}

public enum Unicidade
{
    Outra,
