            [Diego] = Usuario.CadastrarAluno(diego, ads, "Diego Reis", "diegoReis", hash, agora),
            [Renata] = ComSenha(Usuario.CriarPeloSeed(renata, "renataA", agora), hash),
            [Paulo] = ComSenha(Usuario.CriarPeloSeed(paulo, "pauloS", agora), hash),
