    private static IOrderedEnumerable<Guid> Ordenados(MundoDoMural mundo, params string[] emails) =>
        emails.Select(mundo.Id).Order();

    private static async Task AlterarAsync(MundoDoMural mundo, Func<IServiceProvider, DateTimeOffset, Task> alterar)
    {
        await using var scope = mundo.Factory.Services.CreateAsyncScope();
        await alterar(scope.ServiceProvider, mundo.Relogio.GetUtcNow());
        await scope.ServiceProvider.GetRequiredService<Maxx.Infrastructure.Persistence.MaxxDbContext>().SaveChangesAsync(Ct);
    }
