    );
    const daProfessora = comToken(
      await token(request, professora.email, professora.senha),
    );
    const doAluno = comToken(await token(request, aluno.email, aluno.senha));

    const feed = path.join(info.outputDir, "feed.jpg");
    const grade = path.join(info.outputDir, "grade.jpg");
    await fotoDeTeste(page, feed, 1080, "#4a90d9");
    await fotoDeTeste(page, grade, 320, "#4a90d9");
    const cc = sql(`SELECT id FROM curso WHERE sigla = 'CC';`);

    const publicar = async (
      headers: Record<string, string>,
      data: object,
    ): Promise<string> => {
      const resposta = await request.post("/api/v1/avisos", { headers, data });
      expect(resposta.status()).toBe(201);
      return (await resposta.json()).id as string;
    };

    await publicar(daProfessora, {
      escopo: "turma",
      turmaIds: [professora.turmaId],
      titulo: "Prova integrativa remarcada para 14/08",
      texto: "A prova integrativa de Banco de Dados passou para 14/08, no mesmo horário.",
    });
    const techday = await publicar(daInstituicao, {
      escopo: "curso",
      cursoIds: [cc],
      titulo: "Techday: inscrições abertas",
      texto:
        "As inscrições para o Techday 2026 estão abertas até 20/08. Palestras, oficinas e a feira de projetos dos alunos de Computação.",
      uploadId: await fotoDeAviso(request, daInstituicao, feed, grade),
    });
    // Tudo lido até aqui, inclusive os avisos de outras execuções; o próximo fica não lido.
    expect(
      (await request.post("/api/v1/mural/leitura", { headers: doAluno })).status(),
    ).toBe(204);
    await publicar(daInstituicao, {
      escopo: "faculdade",
      titulo: "Matrícula do 2º semestre até 30/07",
      texto: "Renove sua matrícula para o 2º semestre de 2026 pelo Portal do Aluno até 30/07.",
    });

    await entrar(page, aluno.email, aluno.senha);
    await page.goto("/mural");
    await expect(
      page.getByText("Matrícula do 2º semestre até 30/07").first(),
    ).toBeVisible();
    await page.screenshot({ path: path.join(SAIDA, `mural-${tema}.png`) });

    await page.goto(`/aviso/${techday}`);
    await expect(page.getByTestId("foto-do-aviso")).toBeVisible();
    await page.waitForTimeout(1500);
    await page.screenshot({ path: path.join(SAIDA, `aviso-${tema}.png`) });

    // O vazio: outro aluno, sem turma, no filtro dos professores.
    const semTurma = await novaConta(request, "Bruno Lima");
    await page.context().clearCookies();
    await entrar(page, semTurma.email, semTurma.senha);
    await page.goto("/mural");
    await page.getByRole("radio", { name: "Professores" }).click();
    await expect(page.getByText("Nenhum aviso dos professores.")).toBeVisible();
    await page.screenshot({ path: path.join(SAIDA, `vazio-${tema}.png`) });
  },
