import path from "node:path";

import { expect, test, type Page } from "@playwright/test";

import { sql } from "./apoio/contas";
import { novaProfessora } from "./apoio/medalhas";
import { fotoDeTeste } from "./apoio/premios";

const SAIDA = process.env.MAXX_CAPTURAS!;

async function entrar(page: Page, identificador: string, senha: string) {
  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(identificador);
  await page.getByLabel("Senha", { exact: true }).fill(senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await expect(page.getByRole("tab", { name: /Mural/ })).toBeVisible();
}

test("capturas do novo aviso", { tag: "@celular" }, async ({ page, request }, info) => {
  test.setTimeout(120_000);
  const tema = info.project.name.includes("escuro") ? "escuro" : "claro";
  const professora = await novaProfessora(request);

  // Uma segunda turma vigente de CC, para os chips mostrarem mais de uma.
  sql(
    `INSERT INTO vinculo_professor (id, professor_id, turma_id)
     SELECT gen_random_uuid(), c.id, t.id
     FROM cadastro_elegivel c, turma t JOIN materia m ON m.id = t.materia_id
     WHERE c.email = '${professora.email}' AND m.nome = 'Algoritmos e Programação'
       AND t.semestre_letivo_id = (SELECT semestre_letivo_id FROM turma WHERE id = '${professora.turmaId}');`,
  );

  const foto = path.join(SAIDA, `aviso-foto-${tema}.jpg`);
  await fotoDeTeste(page, foto, 1080, "#4a90d9");

  await entrar(page, professora.email, professora.senha);
  await page.goto("/mural");
  await page.getByRole("button", { name: "Novo aviso" }).click();
  await expect(page.getByRole("heading", { name: "Novo aviso" })).toBeVisible();

  await page.getByRole("checkbox", { name: /Banco de Dados/ }).click();
  await page.getByLabel("Título").fill("Prova integrativa remarcada para 14/08");
  await page
    .getByLabel("Texto")
    .fill("A prova integrativa passou para 14/08, no mesmo horário e na mesma sala.");
  await page.screenshot({ path: path.join(SAIDA, `novo-aviso-${tema}.png`) });

  const seletor = page.waitForEvent("filechooser");
  await page.getByRole("button", { name: "Escolher foto" }).click();
  await (await seletor).setFiles(foto);
  await expect(page.getByTestId("previa-da-foto")).toBeVisible();
  await page.getByRole("button", { name: "Publicar aviso" }).scrollIntoViewIfNeeded();
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(SAIDA, `novo-aviso-foto-${tema}.png`) });
});

