  await page.getByRole("button", { name: "Publicar aviso" }).scrollIntoViewIfNeeded();
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(SAIDA, `novo-aviso-foto-${tema}.png`) });
});

