  ],
  // layout-grid do Lucide: a aba da grade de posts no perfil.
  grade: [
    { x: 3, y: 3, width: 7, height: 7, rx: 1 },
    { x: 14, y: 3, width: 7, height: 7, rx: 1 },
    { x: 14, y: 14, width: 7, height: 7, rx: 1 },
    { x: 3, y: 14, width: 7, height: 7, rx: 1 },
  ],
