  return useMutation({
    mutationFn: async () => {
      const { error, response } = await client.PUT("/api/v1/eu/trofeus/visto");
      if (!response.ok) {
        throw FalhaDaApi.doCorpo(error);
      }
    },
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ["novidades"] }),
  });
}

