import type { IconName } from "../components/Icon";

// O texto de cada notificação é do app, pelo tipo (decisoes/README.md, Notificação). A API
// manda só o que a frase pede: o nome do item, o motivo, a decisão, o post, o título do
// aviso.
export interface DadosDaNotificacao {
  tipo: string;
  referenciaId: string;
  item?: string | null;
  motivo?: string | null;
  decisao?: string | null;
  postId?: string | null;
  tituloDoAviso?: string | null;
}

interface Apresentacao {
  texto: string;
  icone: IconName;
  // Para onde o toque leva (passo 10, pergunta 6); nulo, nenhum destino.
  destino: string | null;
}

const comMotivo = (frase: string, motivo?: string | null) =>
  motivo ? `${frase}: ${motivo.replace(/\.?\s*$/, "")}.` : `${frase}.`;

// Um tipo por linha; o teste confere que todo tipo da API tem a sua. Um tipo que o app
// instalado ainda não conhece (a API anda na frente) cai no texto genérico.
export const APRESENTACOES: Record<
  string,
  (dados: DadosDaNotificacao) => Apresentacao
> = {
  medalhaRecebida: ({ item }) => ({
    texto: `Você recebeu a medalha ${item ?? "de um professor"}.`,
    icone: "fita",
    destino: "/trofeus",
  }),
  comprovacaoAprovada: ({ item, postId }) => ({
    texto: `Sua comprovação de ${item ?? "prêmio"} foi aprovada.`,
    icone: "taca",
    destino: postId ? `/post/${postId}` : "/trofeus",
  }),
  comprovacaoReprovada: ({ item, motivo }) => ({
    texto: comMotivo(`Sua comprovação de ${item ?? "prêmio"} foi reprovada`, motivo),
    icone: "taca",
    destino: "/trofeus",
  }),
  contestacaoAberta: ({ item, postId }) => ({
    texto: `Seu prêmio ${item ?? ""} foi contestado e está em averiguação.`.replace(
      "  ",
      " ",
    ),
    icone: "taca",
    destino: postId ? `/post/${postId}` : "/trofeus",
  }),
  decisaoDeContestacao: ({ item, decisao, motivo, postId }) => ({
    texto:
      decisao === "revogada"
        ? comMotivo(`A contestação de ${item ?? "seu prêmio"} terminou e o prêmio foi revogado`, motivo)
        : `A contestação de ${item ?? "seu prêmio"} terminou e o prêmio foi confirmado.`,
    icone: "taca",
    destino: postId ? `/post/${postId}` : "/trofeus",
  }),
  premioRevogado: ({ item, motivo }) => ({
    texto: comMotivo(`Seu prêmio ${item ?? ""} foi revogado`.replace("  ", " "), motivo),
    icone: "taca",
    destino: "/trofeus",
  }),
  conquistaObtida: ({ item }) => ({
    texto: `Você obteve a conquista ${item ?? "nova"}.`,
    icone: "taca",
    destino: "/trofeus",
  }),
  conquistaRemovida: ({ item }) => ({
    texto: `A conquista ${item ?? ""} foi removida no recálculo dos seus prêmios.`.replace(
      "  ",
      " ",
    ),
    icone: "taca",
    destino: "/trofeus",
  }),
  avisoNovo: ({ referenciaId, tituloDoAviso }) => ({
    texto: tituloDoAviso
      ? `Aviso novo no Mural: ${tituloDoAviso}`
      : "Aviso novo no Mural.",
    icone: "newspaper",
    destino: `/aviso/${referenciaId}`,
  }),
};

export function apresentar(dados: DadosDaNotificacao): Apresentacao {
  const montar = APRESENTACOES[dados.tipo];
  return montar
    ? montar(dados)
    : { texto: "Você tem uma novidade.", icone: "inbox", destino: null };
}

