  await expect(page.getByRole("button", { name: "Novo post" }).first()).toBeVisible();
}

async function ok(resposta: Awaited<ReturnType<APIRequestContext["post"]>>) {
  expect(resposta.ok(), `${resposta.url()}: ${resposta.status()}`).toBe(true);
  return resposta;
}

test("capturas das notificações", { tag: "@celular" }, async ({ page, request }, info) => {
  test.setTimeout(240_000);
  const tema = info.project.name.includes("escuro") ? "escuro" : "claro";
  const instituicao = await novaInstituicao(request);
  const professora = await novaProfessora(request);
  const aluna = await novaConta(request, "Ana Souza");
  matricular(aluna, professora.turmaId);
  const daInstituicao = comToken(await token(request, instituicao.email, instituicao.senha));
  const daProfessora = comToken(await token(request, professora.email, professora.senha));
  const daAluna = comToken(await token(request, aluna.email, aluna.senha));

  // Cinco medalhas fecham a C01 (Cinco no bimestre); anular uma a remove no recálculo.
  const alunos = await (
    await request.get(`/api/v1/professor/turmas/${professora.turmaId}/alunos`, { headers: daProfessora })
  ).json();
  const alunaId = alunos.find((a: { nomeDeExibicao: string }) => a.nomeDeExibicao === "Ana Souza").id;
  let ultima = "";
  for (const item of ["M01", "M01", "M02", "M02", "M03"]) {
    const resposta = await ok(
      await request.post(`/api/v1/professor/turmas/${professora.turmaId}/medalhas`, {
        headers: daProfessora,
        data: { alunoId: alunaId, item },
      }),
    );
    ultima = (await resposta.json()).id;
  }
  const conquistas = () =>
    sql(`SELECT count(*) FROM notificacao WHERE usuario_id = '${alunaId}' AND tipo = 'conquistaObtida';`);
  await expect.poll(conquistas, { timeout: 30_000 }).toBe("1");
  anularMedalha(ultima);

  // Três reivindicações com foto: uma reprovada; uma aprovada, contestada e revogada; uma
  // aprovada e removida pela instituição.
  const feed = path.join(SAIDA, `notif-feed-${tema}.jpg`);
  const grade = path.join(SAIDA, `notif-grade-${tema}.jpg`);
  await fotoDeTeste(page, feed, 1080, "#4a90d9");
  await fotoDeTeste(page, grade, 320, "#4a90d9");
  const hoje = new Date();
  const dia = (atras: number) => {
    const data = new Date(hoje.getTime() - atras * 86_400_000);
    return data.toISOString().slice(0, 10);
  };
  const reivindicar = async (nome: string, atras: number) => {
    const resposta = await ok(
      await request.post("/api/v1/reivindicacoes", {
        headers: daAluna,
        data: {
          item: "P01",
          eventoDigitado: { nome, inicio: dia(atras), fim: dia(atras) },
          uploadId: await fotoEnviada(request, daAluna.Authorization.slice(7), feed, grade),
        },
      }),
    );
    const post = await resposta.json();
    const comprovacao = sql(`SELECT id FROM comprovacao WHERE premio_participacao_id = '${post.premio.id}';`);
    return { postId: post.id as string, premioId: post.premio.id as string, comprovacao };
  };

  const reprovada = await reivindicar("Palestra de carreira", 1);
  await ok(
    await request.post(`/api/v1/comprovacoes/${reprovada.comprovacao}/reprovacao`, {
      headers: daInstituicao,
      data: { motivo: "Foto de outro evento." },
    }),
  );

  const contestada = await reivindicar("Palestra de abertura", 2);
  await ok(await request.post(`/api/v1/comprovacoes/${contestada.comprovacao}/aprovacao`, { headers: daInstituicao }));
  const contestacao = await (
    await ok(
      await request.post(`/api/v1/premios-participacao/${contestada.premioId}/contestacao`, {
        headers: daProfessora,
        data: { motivo: "A foto não é da palestra." },
      }),
    )
  ).json();
  await ok(
    await request.post(`/api/v1/contestacoes/${contestacao.id}/revogacao`, {
      headers: daInstituicao,
      data: { motivo: "Foto repetida de outra palestra." },
    }),
  );

  const removida = await reivindicar("Palestra de tecnologia", 3);
  await ok(await request.post(`/api/v1/comprovacoes/${removida.comprovacao}/aprovacao`, { headers: daInstituicao }));
  expect((await request.delete(`/api/v1/posts/${removida.postId}`, { headers: daInstituicao })).status()).toBe(204);

  await ok(
    await request.post("/api/v1/avisos", {
      headers: daInstituicao,
      data: { escopo: "faculdade", titulo: "Matrícula do 2º semestre até 30/07", texto: "Renove pelo Portal do Aluno." },
    }),
  );

  // O worker grava as notificações fora da requisição.
  const tipos = () =>
    sql(`SELECT count(DISTINCT tipo) FROM notificacao WHERE usuario_id = '${alunaId}';`);
  await expect.poll(tipos, { timeout: 60_000 }).toBe("9");

  await entrar(page, aluna.email, aluna.senha);
  await expect(page.getByTestId("novidade-sininho")).toBeVisible({ timeout: 15_000 });
  await expect(page.getByTestId("novidade-Mural")).toBeVisible();
  await expect(page.getByTestId("novidade-Troféus")).toBeVisible();
  await page.screenshot({ path: path.join(SAIDA, `feed-sininho-${tema}.png`) });

  await page.getByRole("tab", { name: /Mural/ }).click();
  await expect(page.getByText("Matrícula do 2º semestre até 30/07").first()).toBeVisible();
  await expect(page.getByTestId("novidade-sininho")).toBeVisible();
  await page.screenshot({ path: path.join(SAIDA, `mural-sininho-${tema}.png`) });

  await page.getByRole("button", { name: "Notificações, com novidade" }).click();
  await expect(page.getByText("Aviso novo no Mural: Matrícula do 2º semestre até 30/07")).toBeVisible();
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(SAIDA, `notificacoes-${tema}.png`) });
  await page.getByText("Você recebeu a medalha Presença integral.").first().scrollIntoViewIfNeeded().catch(() => {});
  await page.mouse.wheel(0, 2000);
  await page.waitForTimeout(800);
  await page.screenshot({ path: path.join(SAIDA, `notificacoes-fim-${tema}.png`) });
});

